export const filterSamplesLocally = (params) => {
  const { product_type = 'ALL', weave = 'ALL', yarn = 'ALL', blend = '', finish = '', finish_type = 'ALL', gsm_min, gsm_max, feel_terms = '' } = params;

  let results = [...FALLBACK_SAMPLES];

  if (product_type && product_type.toUpperCase() !== 'ALL') {
    results = results.filter((s) => s.product && s.product.toUpperCase().includes(product_type.toUpperCase()));
  }
  if (weave && weave.toUpperCase() !== 'ALL') {
    results = results.filter((s) => s.weave && s.weave.toUpperCase().includes(weave.toUpperCase()));
  }
  if (yarn && yarn.toUpperCase() !== 'ALL') {
    results = results.filter((s) => s.yarn && s.yarn.toUpperCase().includes(yarn.toUpperCase()));
  }
  if (blend && blend.trim() && blend.toUpperCase() !== 'ALL') {
    const b = blend.trim().toLowerCase();
    results = results.filter((s) => s.blend && s.blend.toLowerCase().includes(b));
  }
  const effectiveFinish = (finish_type && finish_type.toUpperCase() !== 'ALL') ? finish_type : finish;
  if (effectiveFinish && effectiveFinish.trim() && effectiveFinish.toUpperCase() !== 'ALL') {
    const f = effectiveFinish.trim().toLowerCase();
    results = results.filter((s) => s.finish && s.finish.toLowerCase().includes(f));
  }
  if (gsm_min !== undefined && gsm_min !== '') {
    const minVal = Number(gsm_min);
    if (!isNaN(minVal)) {
      results = results.filter((s) => Number(s.gsm) >= minVal);
    }
  }
  if (gsm_max !== undefined && gsm_max !== '') {
    const maxVal = Number(gsm_max);
    if (!isNaN(maxVal)) {
      results = results.filter((s) => Number(s.gsm) <= maxVal);
    }
  }

  return {
    results,
    total_count: results.length,
    standard_terms: feel_terms ? feel_terms.split(',').map((t) => t.trim()).filter(Boolean) : [],
  };
};
